//! Real evaluator-6 evidence, not outcomes generated by revision 7 and relabeled.
use dlms_learning_lab::{
    backup,
    engine::{Goal, State},
    pack::{self, Scenario},
    progress::{self, Attempt, MigrationReceipts, Progress},
    script_teaching, shell, storage_teaching, workspace,
};
use serde::Deserialize;
use std::{
    path::Path,
    sync::atomic::{AtomicBool, AtomicUsize},
};

#[derive(Deserialize)]
struct OldAuthored {
    id: String,
    scenario_version: u32,
    cases: Vec<shell::Case>,
    record: shell::Record,
}
fn records() -> Vec<OldAuthored> {
    serde_json::from_str(include_str!("fixtures/shell-v6-authored-records.json")).unwrap()
}
fn empty() -> Progress {
    Progress {
        schema_version: 1,
        ..Default::default()
    }
}
fn old_profile(labs: &[Scenario]) -> Progress {
    let mut p = empty();
    p.clock = 315;
    for (i, old) in records().into_iter().enumerate() {
        let lab = labs.iter().find(|s| s.id == old.id).unwrap();
        assert_eq!(lab.version, old.scenario_version);
        let Goal::Script { cases } = &lab.goal else {
            panic!()
        };
        assert_eq!(
            serde_json::to_value(cases).unwrap(),
            serde_json::to_value(old.cases).unwrap()
        );
        assert_eq!(old.record.engine_revision, 6);
        assert!(old.record.valid());
        let mut a = Attempt::new(lab, i as u64 + 1);
        a.state = State::Script {
            source: old.record.source.clone(),
            run: Some(old.record),
        };
        p.attempts.insert(lab.id.clone(), a);
        p.favorites.insert(lab.id.clone());
    }
    p
}
fn bytes(p: &Progress) -> Vec<u8> {
    serde_json::to_vec_pretty(p).unwrap()
}
fn receipts(path: &Path) -> serde_json::Value {
    serde_json::from_slice::<serde_json::Value>(&std::fs::read(path).unwrap()).unwrap()["migration_receipts"].clone()
}
fn inspect(path: &Path, labs: &[Scenario]) -> Result<backup::Candidate, String> {
    backup::inspect(path, labs, &AtomicBool::new(false), &AtomicUsize::new(0))
}
fn shell_copy(path: &Path) -> std::path::PathBuf {
    path.with_extension("before-shell-v7.json")
}

#[test]
fn all_33_actual_v6_records_and_182_outcomes_remain_history_until_explicit_rerun() {
    let labs = pack::bundled().unwrap();
    let p = old_profile(&labs);
    assert_eq!(p.attempts.len(), 33);
    let before = bytes(&p);
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    std::fs::write(&path, &before).unwrap();
    let mut loaded = progress::load(&path, &labs).unwrap();
    assert_eq!(std::fs::read(&path).unwrap(), before, "load must not write");
    let mut outcomes = 0;
    for (id, a) in &mut loaded.attempts {
        let lab = labs.iter().find(|s| &s.id == id).unwrap();
        assert!(!progress::current_solved(a, lab));
        assert!(progress::legacy_script_credit(a, lab));
        let State::Script {
            run: Some(record), ..
        } = &a.state
        else {
            panic!()
        };
        let old = record.clone();
        outcomes += old.results.len();
        workspace::prepare(a);
        assert_eq!(
            a.workspace.as_ref().unwrap().script_history.as_ref(),
            Some(&old)
        );
        let State::Script { source, run } = &mut a.state else {
            panic!()
        };
        assert_eq!(source, &old.source);
        assert!(run.is_none());
    }
    assert_eq!(outcomes, 182);
    progress::save(&path, &loaded).unwrap();
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), before);
    assert_eq!(receipts(&path)["shell"], serde_json::json!([7]));
    assert!(
        loaded.migration_receipts.is_none(),
        "writer must not stamp caller"
    );
    let mut loaded = progress::load(&path, &labs).unwrap();
    for (id, a) in &mut loaded.attempts {
        let lab = labs.iter().find(|s| &s.id == id).unwrap();
        let Goal::Script { cases } = &lab.goal else {
            panic!()
        };
        let State::Script { source, run } = &mut a.state else {
            panic!()
        };
        *run = Some(shell::Record {
            engine_revision: shell::EVALUATOR_REVISION,
            source: source.clone(),
            results: cases.iter().map(|c| shell::run(source, c)).collect(),
        });
        assert!(progress::current_solved(a, lab));
        assert!(progress::legacy_script_credit(a, lab));
        assert_eq!(
            a.workspace
                .as_ref()
                .unwrap()
                .script_history
                .as_ref()
                .unwrap()
                .engine_revision,
            6
        );
    }
    progress::save(&path, &loaded).unwrap();
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), before);
    assert_eq!(progress::load(&path, &labs).unwrap().favorites, p.favorites);
}

#[test]
fn formerly_unsupported_capture_is_not_credited_or_rewritten_until_explicit_rerun() {
    let mut labs = pack::bundled().unwrap();
    let row: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/shell-v6-substitution-before.json")).unwrap();
    let source = row[0]["source"].as_str().unwrap().to_owned();
    let case: shell::Case = serde_json::from_value(row[0]["case"].clone()).unwrap();
    let result: shell::Outcome =
        serde_json::from_value(row[0]["native_revision6_outcome"].clone()).unwrap();
    let lab = labs
        .iter_mut()
        .find(|s| matches!(s.goal, Goal::Script { .. }))
        .unwrap();
    lab.goal = Goal::Script {
        cases: vec![case.clone()],
    };
    let mut a = Attempt::new(lab, 1);
    let record = shell::Record {
        engine_revision: 6,
        source: source.clone(),
        results: vec![result],
    };
    a.state = State::Script {
        source: source.clone(),
        run: Some(record.clone()),
    };
    assert!(!progress::current_solved(&a, lab));
    assert!(!progress::legacy_script_credit(&a, lab));
    workspace::prepare(&mut a);
    assert_eq!(
        a.workspace.as_ref().unwrap().script_history.as_ref(),
        Some(&record)
    );
    let State::Script { run, .. } = &mut a.state else {
        panic!()
    };
    *run = Some(shell::Record {
        engine_revision: 7,
        source: source.clone(),
        results: vec![shell::run(&source, &case)],
    });
    assert!(progress::current_solved(&a, lab));
    assert_eq!(
        a.workspace.as_ref().unwrap().script_history.as_ref(),
        Some(&record)
    );
}

#[test]
fn first_write_rejects_an_occupied_valid_but_different_slot_including_whitespace() {
    for equivalent in [false, true] {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("progress.json");
        let mut old = empty();
        old.clock = 4;
        let original = bytes(&old);
        std::fs::write(&path, &original).unwrap();
        let occupied = if equivalent {
            serde_json::to_vec(&old).unwrap()
        } else {
            bytes(&empty())
        };
        assert_ne!(occupied, original);
        std::fs::write(shell_copy(&path), &occupied).unwrap();
        let mut candidate = empty();
        candidate.migration_receipts = Some(MigrationReceipts {
            workspace: true,
            shell: vec![7],
        });
        assert!(
            progress::save(&path, &candidate)
                .unwrap_err()
                .contains("differs")
        );
        assert_eq!(std::fs::read(&path).unwrap(), original);
        assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), occupied);
        assert_eq!(candidate.migration_receipts.unwrap().shell, vec![7]);
    }
}

#[test]
fn reset_first_uses_actual_disk_and_preserves_old_bytes_even_without_any_candidate_run() {
    let labs = pack::bundled().unwrap();
    let p = old_profile(&labs);
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    let original = bytes(&p);
    std::fs::write(&path, &original).unwrap();
    progress::save(&path, &empty()).unwrap();
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), original);
    assert!(progress::load(&path, &labs).unwrap().attempts.is_empty());
}

#[test]
fn practice_only_actual_v6_result_survives_repeat_saves_with_legacy_history() {
    let mut labs = pack::bundled().unwrap();
    let old = records().remove(0);
    let lab = labs.iter_mut().find(|s| s.id == old.id).unwrap();
    let lesson = lab.teaching.as_mut().unwrap();
    lesson.example = old.record.source.clone();
    lesson.fixture = old.cases[0].clone();
    let mut a = Attempt::new(lab, 1);
    workspace::prepare(&mut a);
    script_teaching::prepare(&mut a, lab.teaching.as_ref().unwrap(), true);
    let w = a.workspace.as_mut().unwrap();
    let learning = w.script_learning.as_mut().unwrap();
    learning.example_revision = 6;
    learning.example_result = Some(old.record.results[0].clone());
    w.script_history = Some(old.record.clone());
    assert!(matches!(&a.state, State::Script { run: None, .. }));
    let mut p = empty();
    p.attempts.insert(lab.id.clone(), a);
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    let original = bytes(&p);
    std::fs::write(&path, &original).unwrap();
    let occupied = bytes(&empty());
    std::fs::write(shell_copy(&path), &occupied).unwrap();
    assert!(progress::save(&path, &p).is_err());
    assert_eq!(std::fs::read(&path).unwrap(), original);
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), occupied);
    std::fs::remove_file(shell_copy(&path)).unwrap();
    progress::save(&path, &p).unwrap();
    for clock in 1..=3 {
        p.clock = clock;
        progress::save(&path, &p).unwrap();
        let loaded = progress::load(&path, &labs).unwrap();
        assert_eq!(
            serde_json::to_value(&loaded.attempts).unwrap(),
            serde_json::to_value(&p.attempts).unwrap()
        );
    }
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), original);
}

#[test]
fn workspace_receipt_is_independent_and_survives_reset_remove_and_recreate() {
    let labs = pack::bundled().unwrap();
    let lab = labs
        .iter()
        .find(|s| matches!(s.goal, Goal::Script { .. }))
        .unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    let mut p = empty();
    progress::save(&path, &p).unwrap();
    assert_eq!(receipts(&path)["workspace"], false);
    let original = std::fs::read(&path).unwrap();
    let mut a = Attempt::new(lab, 1);
    workspace::prepare(&mut a);
    p.attempts.insert(lab.id.clone(), a);
    progress::save(&path, &p).unwrap();
    assert_eq!(
        std::fs::read(path.with_extension("before-workspace.json")).unwrap(),
        original
    );
    assert_eq!(receipts(&path)["workspace"], true);
    progress::save(&path, &empty()).unwrap();
    progress::save(&path, &p).unwrap();
    assert_eq!(
        std::fs::read(path.with_extension("before-workspace.json")).unwrap(),
        original
    );
    // A receipt records an already handled boundary, not continued integrity of an external file.
    std::fs::remove_file(path.with_extension("before-workspace.json")).unwrap();
    progress::save(&path, &p).unwrap();
    assert!(!path.with_extension("before-workspace.json").exists());
}

#[test]
fn portable_exports_strip_receipts_and_imported_receipts_cannot_skip_target_backup() {
    let labs = pack::bundled().unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    progress::save(&path, &empty()).unwrap();
    let loaded = progress::load(&path, &labs).unwrap();
    assert!(loaded.migration_receipts.is_some());
    let export = dir.path().join("export.json");
    backup::export(&export, &loaded, &labs).unwrap();
    let value: serde_json::Value =
        serde_json::from_slice(&std::fs::read(&export).unwrap()).unwrap();
    assert!(value["progress"].get("migration_receipts").is_none());
    let mut crafted = serde_json::to_value(empty()).unwrap();
    crafted["migration_receipts"] = serde_json::json!({"workspace":true,"shell":[7]});
    let input = dir.path().join("crafted.json");
    std::fs::write(&input, serde_json::to_vec(&crafted).unwrap()).unwrap();
    let candidate = inspect(&input, &labs).unwrap();
    assert!(candidate.progress.migration_receipts.is_none());
    let target = dir.path().join("old.json");
    let original = bytes(&empty());
    std::fs::write(&target, &original).unwrap();
    backup::restore(&target, &candidate, &labs).unwrap();
    assert_eq!(std::fs::read(shell_copy(&target)).unwrap(), original);
    assert_eq!(receipts(&target)["shell"], serde_json::json!([7]));
    for target in [dir.path().join("new.json"), path] {
        let own = inspect(&export, &labs).unwrap();
        backup::restore(&target, &own, &labs).unwrap();
        progress::save(&target, &own.progress).unwrap();
    }
}

#[test]
fn invalid_or_future_provenance_is_rejected_before_import_or_normal_write() {
    let labs = pack::bundled().unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("input.json");
    for receipt in [
        serde_json::json!({"shell":[8]}),
        serde_json::json!({"shell":[0]}),
        serde_json::json!({"shell":[7,7]}),
        serde_json::json!({"shell":[7,6]}),
        serde_json::json!({"shell":"7"}),
        serde_json::json!({"shell":[7],"extra":true}),
    ] {
        let mut value = serde_json::to_value(empty()).unwrap();
        value["migration_receipts"] = receipt;
        let original = serde_json::to_vec(&value).unwrap();
        std::fs::write(&path, &original).unwrap();
        assert!(progress::load(&path, &labs).is_err());
        assert!(inspect(&path, &labs).is_err());
        assert!(progress::save(&path, &empty()).is_err());
        assert_eq!(std::fs::read(&path).unwrap(), original);
    }
}

#[test]
fn confirmed_restore_recovers_corrupt_or_future_target_with_exact_raw_safety_copy() {
    let labs = pack::bundled().unwrap();
    for original in [b"{ broken data }".to_vec(), b"{\"schema_version\":99,\"clock\":0,\"favorites\":[],\"attempts\":{}}".to_vec(), b"{\"schema_version\":1,\"clock\":0,\"favorites\":[],\"attempts\":{},\"migration_receipts\":{\"shell\":[8]}}".to_vec()] {
        let dir = tempfile::tempdir().unwrap();
        let input = dir.path().join("input.json");
        backup::export(&input, &empty(), &labs).unwrap();
        let target = dir.path().join("progress.json");
        std::fs::write(&target, &original).unwrap();
        let occupied = b"unrelated prior migration slot";
        std::fs::write(shell_copy(&target), occupied).unwrap();
        assert!(progress::load(&target, &labs).is_err());
        assert!(progress::save(&target, &empty()).is_err());
        let candidate = inspect(&input, &labs).unwrap();
        assert_eq!(std::fs::read(&target).unwrap(), original, "preview is read-only");
        let restored = backup::restore(&target, &candidate, &labs).unwrap();
        assert_eq!(std::fs::read(restored.safety_copy.unwrap()).unwrap(), original);
        assert_eq!(std::fs::read(shell_copy(&target)).unwrap(), occupied, "recovery is not an old6 classification");
        assert_eq!(receipts(&target)["shell"], serde_json::json!([7]));
        progress::save(&target, &empty()).unwrap();
    }
}

#[test]
fn restore_first_respects_exact_migration_conflicts_without_touching_target_or_import() {
    let labs = pack::bundled().unwrap();
    let dir = tempfile::tempdir().unwrap();
    let input = dir.path().join("input.json");
    backup::export(&input, &empty(), &labs).unwrap();
    let import_bytes = std::fs::read(&input).unwrap();
    let target = dir.path().join("progress.json");
    let original = bytes(&empty());
    std::fs::write(&target, &original).unwrap();
    let different = b"{\"schema_version\":1,\"clock\":9,\"favorites\":[],\"attempts\":{}}";
    std::fs::write(shell_copy(&target), different).unwrap();
    let candidate = inspect(&input, &labs).unwrap();
    assert!(backup::restore(&target, &candidate, &labs).is_err());
    assert_eq!(std::fs::read(&target).unwrap(), original);
    assert_eq!(std::fs::read(&input).unwrap(), import_bytes);
    assert!(!dir.path().join("progress-before-restore-1.json").exists());
}

#[test]
fn m54_storage_live_state_invalid_pending_draft_and_separate_practice_survive_upgrade() {
    let mut labs = pack::bundled().unwrap();
    let lab = pack::load(include_str!("fixtures/storage-workspace-preview.json"))
        .unwrap()
        .remove(0);
    let mut a = Attempt::new(&lab, 8);
    workspace::prepare(&mut a);
    storage_teaching::prepare(&mut a, lab.storage_teaching.as_ref().unwrap(), true);
    let w = a.workspace.as_mut().unwrap();
    w.storage_draft.as_mut().unwrap().text = "unfinished learner draft\n".into();
    let learning = w.storage_learning.as_mut().unwrap();
    learning.draft.text = "independent practice draft\n".into();
    learning.view = script_teaching::View::Example;
    let expected = serde_json::to_value(&a).unwrap();
    let mut p = old_profile(&labs);
    p.attempts.insert(lab.id.clone(), a);
    labs.push(lab);
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    let original = bytes(&p);
    std::fs::write(&path, &original).unwrap();
    progress::save(&path, &p).unwrap();
    let loaded = progress::load(&path, &labs).unwrap();
    assert_eq!(
        serde_json::to_value(&loaded.attempts["test-storage-workspace"]).unwrap(),
        expected
    );
    let export = dir.path().join("export.json");
    backup::export(&export, &loaded, &labs).unwrap();
    let candidate = inspect(&export, &labs).unwrap();
    let target = dir.path().join("restored.json");
    backup::restore(&target, &candidate, &labs).unwrap();
    let restored = progress::load(&target, &labs).unwrap();
    assert_eq!(
        serde_json::to_value(&restored.attempts["test-storage-workspace"]).unwrap(),
        expected
    );
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), original);
}

#[test]
fn edited_assignment_draft_is_not_executed_or_replaced_by_history_migration() {
    let labs = pack::bundled().unwrap();
    let mut p = old_profile(&labs);
    let id = p.attempts.keys().next().unwrap().clone();
    let a = p.attempts.get_mut(&id).unwrap();
    let State::Script { source, run } = &mut a.state else {
        panic!()
    };
    let old = run.clone().unwrap();
    *source = "printf '%s' \"$(printf 'unsaved revised draft')\"".into();
    let edited = source.clone();
    let original = bytes(&p);
    let mut decoded = progress::decode(&original, &labs).unwrap();
    let a = decoded.attempts.get_mut(&id).unwrap();
    workspace::prepare(a);
    assert!(matches!(&a.state, State::Script { source, run: None } if source == &edited));
    assert_eq!(
        a.workspace.as_ref().unwrap().script_history.as_ref(),
        Some(&old)
    );
    let lab = labs.iter().find(|s| s.id == id).unwrap();
    assert!(!progress::current_solved(a, lab));
    assert!(progress::legacy_script_credit(a, lab));
}

#[test]
fn full_32_record_history_rejects_extra_legacy_run_without_discarding_any_record() {
    let labs = pack::bundled().unwrap();
    let mut old = records();
    let first = old.remove(0);
    let lab = labs.iter().find(|s| s.id == first.id).unwrap();
    let mut a = Attempt::new(lab, 1);
    workspace::prepare(&mut a);
    let w = a.workspace.as_mut().unwrap();
    w.script_history = Some(old.remove(0).record);
    w.script_history_more = old.into_iter().map(|r| r.record).collect();
    assert_eq!(w.script_history_more.len(), 31);
    let mut p = empty();
    p.attempts.insert(lab.id.clone(), a);
    let exact_32 = bytes(&p);
    assert!(progress::decode(&exact_32, &labs).is_ok());
    let a = p.attempts.get_mut(&lab.id).unwrap();
    a.state = State::Script {
        source: first.record.source.clone(),
        run: Some(first.record),
    };
    assert!(!workspace::can_preserve_script_history(a));
    let overflow = bytes(&p);
    assert!(
        progress::decode(&overflow, &labs)
            .err()
            .unwrap()
            .contains("history")
    );
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    std::fs::write(&path, &exact_32).unwrap();
    assert!(progress::save(&path, &p).is_err());
    assert_eq!(std::fs::read(&path).unwrap(), exact_32);
    let mut future: serde_json::Value = serde_json::from_slice(&exact_32).unwrap();
    future["attempts"][&lab.id]["workspace"]["script_history"]["engine_revision"] =
        serde_json::json!(8);
    assert!(progress::decode(&serde_json::to_vec(&future).unwrap(), &labs).is_err());
}

#[test]
fn completed_shell_receipt_does_not_claim_external_snapshot_integrity() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    std::fs::write(&path, bytes(&empty())).unwrap();
    progress::save(&path, &empty()).unwrap();
    std::fs::remove_file(shell_copy(&path)).unwrap();
    progress::save(&path, &empty()).unwrap();
    assert!(!shell_copy(&path).exists());
    let replacement = b"external replacement, not authenticated by a receipt";
    std::fs::write(shell_copy(&path), replacement).unwrap();
    progress::save(&path, &empty()).unwrap();
    assert_eq!(std::fs::read(shell_copy(&path)).unwrap(), replacement);
}

#[cfg(unix)]
#[test]
fn failed_raw_restore_safety_copy_preserves_target_import_and_candidate() {
    let labs = pack::bundled().unwrap();
    let dir = tempfile::tempdir().unwrap();
    let target = dir.path().join("progress.json");
    let original = b"bounded corrupt original";
    std::fs::write(&target, original).unwrap();
    let input = dir.path().join("import.json");
    backup::export(&input, &empty(), &labs).unwrap();
    let incoming = std::fs::read(&input).unwrap();
    let candidate = inspect(&input, &labs).unwrap();
    // A dangling path is still occupied: no-clobber must reject it, never follow it.
    let occupied = dir.path().join("progress-before-restore-1.json");
    std::os::unix::fs::symlink(dir.path().join("never-created"), &occupied).unwrap();
    assert!(backup::restore(&target, &candidate, &labs).is_err());
    assert_eq!(std::fs::read(&target).unwrap(), original);
    assert_eq!(std::fs::read(&input).unwrap(), incoming);
    assert!(candidate.progress.migration_receipts.is_none());
    assert!(
        std::fs::symlink_metadata(occupied)
            .unwrap()
            .file_type()
            .is_symlink()
    );
    assert!(!dir.path().join("never-created").exists());
    assert!(!shell_copy(&target).exists());
}

#[test]
fn direct_candidate_future_receipt_cannot_be_stripped_into_a_successful_write_or_export() {
    let labs = pack::bundled().unwrap();
    let dir = tempfile::tempdir().unwrap();
    let target = dir.path().join("progress.json");
    let original = bytes(&empty());
    std::fs::write(&target, &original).unwrap();
    let mut p = empty();
    p.migration_receipts = Some(MigrationReceipts {
        workspace: false,
        shell: vec![8],
    });
    assert!(progress::save(&target, &p).is_err());
    assert!(backup::export(&dir.path().join("export.json"), &p, &labs).is_err());
    let candidate = backup::Candidate {
        progress: p,
        rechecked: 0,
    };
    assert!(backup::restore(&target, &candidate, &labs).is_err());
    assert_eq!(std::fs::read(&target).unwrap(), original);
    assert!(!shell_copy(&target).exists());
    assert!(!dir.path().join("export.json").exists());
}

#[test]
fn imported_workspace_receipt_cannot_bypass_first_workspace_snapshot_on_a_current_shell_target() {
    let labs = pack::bundled().unwrap();
    let lab = labs
        .iter()
        .find(|s| matches!(s.goal, Goal::Script { .. }))
        .unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("progress.json");
    progress::save(&path, &empty()).unwrap();
    let original = std::fs::read(&path).unwrap();
    assert_eq!(receipts(&path)["workspace"], false);
    let mut p = empty();
    let mut a = Attempt::new(lab, 1);
    workspace::prepare(&mut a);
    p.attempts.insert(lab.id.clone(), a);
    p.migration_receipts = Some(MigrationReceipts {
        workspace: true,
        shell: vec![7],
    });
    let mut other = empty();
    other.clock = 99;
    let occupied = bytes(&other);
    let slot = path.with_extension("before-workspace.json");
    std::fs::write(&slot, &occupied).unwrap();
    assert!(progress::save(&path, &p).is_err());
    let candidate = backup::Candidate {
        progress: p,
        rechecked: 0,
    };
    assert!(backup::restore(&path, &candidate, &labs).is_err());
    assert_eq!(std::fs::read(&path).unwrap(), original);
    assert_eq!(std::fs::read(slot).unwrap(), occupied);
    assert!(!shell_copy(&path).exists());
    assert!(!dir.path().join("progress-before-restore-1.json").exists());
}

#[test]
fn all_five_changed_actual6_resource_and_input_outcomes_survive_as_exact_saved_history() {
    let evidence: serde_json::Value = serde_json::from_str(include_str!(
        "fixtures/shell-v6-resource-before-substitution.json"
    ))
    .unwrap();
    let fixtures = evidence["fixtures"].as_array().unwrap();
    let mut changed = 0;
    for fixture in fixtures {
        let mut labs = pack::bundled().unwrap();
        let lab = labs
            .iter_mut()
            .find(|s| matches!(s.goal, Goal::Script { .. }))
            .unwrap();
        let source = fixture["source"].as_str().unwrap().to_owned();
        let case: shell::Case = serde_json::from_value(fixture["case"].clone()).unwrap();
        let actual6: shell::Outcome =
            serde_json::from_value(fixture["actual_v6_outcome"].clone()).unwrap();
        let current = shell::run(&source, &case);
        if current == actual6 {
            continue;
        }
        changed += 1;
        lab.goal = Goal::Script { cases: vec![case] };
        let mut a = Attempt::new(lab, 1);
        let record = shell::Record {
            engine_revision: 6,
            source: source.clone(),
            results: vec![actual6],
        };
        a.state = State::Script {
            source: source.clone(),
            run: Some(record.clone()),
        };
        workspace::prepare(&mut a);
        assert_eq!(
            a.workspace.as_ref().unwrap().script_history.as_ref(),
            Some(&record)
        );
        let State::Script { run, .. } = &mut a.state else {
            panic!()
        };
        *run = Some(shell::Record {
            engine_revision: 7,
            source,
            results: vec![current],
        });
        assert!(!progress::current_solved(&a, lab));
        let id = lab.id.clone();
        let mut p = empty();
        p.attempts.insert(id.clone(), a);
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("progress.json");
        progress::save(&path, &p).unwrap();
        let loaded = progress::load(&path, &labs).unwrap();
        assert_eq!(
            loaded.attempts[&id]
                .workspace
                .as_ref()
                .unwrap()
                .script_history
                .as_ref(),
            Some(&record)
        );
    }
    assert_eq!(changed, 5);
}
